begin;
select plan(33);
select has_column('public','notification_deliveries','lease_token','delivery has lease token');
select has_function('public','authorize_notification_delivery_send_v1',array['uuid','uuid','text','uuid'],'pre-send preference recheck exists');
select has_table('public','diagnostic_reevaluation_queue','diagnostic reevaluation queue exists');
select has_function('public','claim_notification_deliveries_v1',array['text','integer','integer'],'notification claim RPC exists');
select has_function('public','record_notification_delivery_worker_result_v1',array['uuid','uuid','text','text','text','text','jsonb','text','uuid'],'notification result RPC exists');
select has_function('public','run_domain_automation_schedulers_v1',array['date','integer'],'domain scheduler RPC exists');
select function_privs_are('public','claim_notification_deliveries_v1',array['text','integer','integer'],'authenticated',array[]::text[],'authenticated cannot claim notifications');
select function_privs_are('public','claim_notification_deliveries_v1',array['text','integer','integer'],'service_role',array['EXECUTE'],'service role can claim notifications');
select function_privs_are('public','run_domain_automation_schedulers_v1',array['date','integer'],'authenticated',array[]::text[],'authenticated cannot run schedulers');
select isnt_empty($$select 1 from pg_get_functiondef('public.claim_notification_deliveries_v1(text,integer,integer)'::regprocedure)d where d like '%for update skip locked%'and d like '%leased_until%'$$,'claim is concurrent and lease-aware');
select isnt_empty($$select 1 from pg_get_functiondef('public.record_notification_delivery_worker_result_v1(uuid,uuid,text,text,text,text,jsonb,text,uuid)'::regprocedure)d where d like '%DEAD_LETTER%'and d like '%NotificationDeliveryRetryScheduledV1%'$$,'result supports retry and DLQ evidence');
select isnt_empty($$select 1 from pg_get_functiondef('public.run_domain_automation_schedulers_v1(date,integer)'::regprocedure)d where d like '%pg_try_advisory_xact_lock%'$$,'scheduler rejects a concurrent run through its transaction lock');

-- Isolate the deterministic claim fixture from pre-existing development jobs.
update public.notification_deliveries
set next_attempt_at=clock_timestamp()+interval'1 day'
where status in('PENDING','FAILED')and(next_attempt_at is null or next_attempt_at<=clock_timestamp());

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('13600000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p136@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values('13610000-0000-4000-8000-000000000001','P136 SARL','P136','ACTIVE','13600000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values('13611000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','13600000-0000-4000-8000-000000000001','ACTIVE',clock_timestamp());
insert into public.organization_member_roles(membership_id,role_code)values('13611000-0000-4000-8000-000000000001','CLIENT_OWNER');
insert into public.notification_preference_categories(code,label_fr,label_ar,mandatory)values('P136_RUNTIME','Runtime P136','تشغيل P136',true);
insert into public.notification_mandatory_policy_versions(id,category_code,version,legal_basis,legal_basis_reference,status,effective_from,content_hash)values('13612000-0000-4000-8000-000000000001','P136_RUNTIME',1,'LEGAL_OBLIGATION','P136-LEGAL-BASIS','ACTIVE',clock_timestamp()-interval'1 minute',repeat('d',64));
insert into public.notification_template_versions(id,template_code,version,event_type,category_code,locale,subject_template,body_template,priority,mandatory,channels,status,effective_from,content_hash)values('13620000-0000-4000-8000-000000000001','P136.RUNTIME',1,'P136RuntimeEvent','P136_RUNTIME','fr-MA','Sujet P136','Corps P136','CRITICAL',true,array['IN_APP'],'ACTIVE',clock_timestamp()-interval'1 minute',repeat('a',64));
update public.notification_retry_policy_versions set status='RETIRED'where status='ACTIVE';
insert into public.notification_retry_policy_versions(id,version,max_attempts,base_backoff_seconds,max_backoff_seconds,status,effective_from,content_hash)values('13630000-0000-4000-8000-000000000001',136,2,1,2,'ACTIVE',clock_timestamp()-interval'1 minute',repeat('b',64));
insert into public.notification_instances(id,recipient_user_id,organization_id,template_version_id,category_code,event_type,locale,subject,body,priority,mandatory,mandatory_policy_version_id,legal_basis,deduplication_key,source_aggregate_type,source_aggregate_id,variables_snapshot,correlation_id)values('13640000-0000-4000-8000-000000000001','13600000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','13620000-0000-4000-8000-000000000001','P136_RUNTIME','P136RuntimeEvent','fr-MA','Sujet P136','Corps P136','CRITICAL',true,'13612000-0000-4000-8000-000000000001','LEGAL_OBLIGATION','p136-runtime-dedup','test','136','{}','13650000-0000-4000-8000-000000000001');
insert into public.notification_deliveries(id,notification_id,channel,delivery_mode,status,next_attempt_at)values('13660000-0000-4000-8000-000000000001','13640000-0000-4000-8000-000000000001','IN_APP','IMMEDIATE','PENDING',clock_timestamp()-interval'1 minute');
insert into public.notification_preference_categories(code,label_fr,label_ar,mandatory)values('P136_OPTIONAL','Option P136','خيار P136',false);
insert into public.notification_template_versions(id,template_code,version,event_type,category_code,locale,subject_template,body_template,priority,mandatory,channels,status,effective_from,content_hash)values('13620000-0000-4000-8000-000000000002','P136.OPTIONAL',1,'P136OptionalEvent','P136_OPTIONAL','fr-MA','Option P136','Corps optionnel','NORMAL',false,array['EMAIL'],'ACTIVE',clock_timestamp()-interval'1 minute',repeat('f',64));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);do $$begin perform public.enqueue_notification('13600000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','P136.OPTIONAL','P136OptionalEvent','fr-MA','{}','p136-no-preference','test','no-preference-136','13650000-0000-4000-8000-000000000007');end$$;reset role;
select extensions.is((select d.status from public.notification_deliveries d join public.notification_instances n on n.id=d.notification_id where n.deduplication_key='p136-no-preference'),'SKIPPED','optional email is fail-closed at enqueue without an explicit preference');
insert into public.notification_email_consent_challenges(id,user_id,organization_id,category_code,consent_version,challenge_hash,expires_at,confirmed_at,correlation_id)values('13613000-0000-4000-8000-000000000001','13600000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','P136_OPTIONAL',1,repeat('2',64),clock_timestamp()+interval'30 minutes',clock_timestamp(),'13650000-0000-4000-8000-000000000008');
insert into public.user_notification_preferences(user_id,organization_id,category_code,channel,delivery_mode,locale)values('13600000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','P136_OPTIONAL','EMAIL','IMMEDIATE','fr-MA');
insert into public.notification_instances(id,recipient_user_id,organization_id,template_version_id,category_code,event_type,locale,subject,body,priority,mandatory,deduplication_key,source_aggregate_type,source_aggregate_id,variables_snapshot,correlation_id)values('13640000-0000-4000-8000-000000000002','13600000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','13620000-0000-4000-8000-000000000002','P136_OPTIONAL','P136OptionalEvent','fr-MA','Option P136','Corps optionnel','NORMAL',false,'p136-optional-dedup','test','optional-136','{}','13650000-0000-4000-8000-000000000005');
insert into public.notification_deliveries(id,notification_id,channel,delivery_mode,status,next_attempt_at)values('13660000-0000-4000-8000-000000000002','13640000-0000-4000-8000-000000000002','EMAIL','IMMEDIATE','PENDING',clock_timestamp()+interval'1 hour');
insert into public.client_compliance_cases(id,organization_id,status,created_by)values('13670000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','PROFILE_IN_PROGRESS','13600000-0000-4000-8000-000000000001');
insert into public.catalog_libraries(id,code,slug,status,steward_organization_id,created_by)values('13683000-0000-4000-8000-000000000001','P136_LIBRARY','p136-library','DRAFT','13610000-0000-4000-8000-000000000001','13600000-0000-4000-8000-000000000001');
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,created_by)values('13684000-0000-4000-8000-000000000001','13683000-0000-4000-8000-000000000001','P136.RELEASE.1','DRAFT',repeat('1',64),'13600000-0000-4000-8000-000000000001');
insert into public.questionnaires(id,library_id,code,status,created_by)values('13681000-0000-4000-8000-000000000001','13683000-0000-4000-8000-000000000001','P136_RUNTIME','DRAFT','13600000-0000-4000-8000-000000000001');
insert into public.questionnaire_versions(id,questionnaire_id,library_id,catalog_release_id,version,status,title_fr,title_ar,description_fr,description_ar,audience,engine_version,policy_version,snapshot_hash,change_reason,created_by)values('13682000-0000-4000-8000-000000000001','13681000-0000-4000-8000-000000000001','13683000-0000-4000-8000-000000000001','13684000-0000-4000-8000-000000000001',1,'DRAFT','Diagnostic P136','تشخيص P136','Fixture diagnostic autoritative','تركيبة تشخيص موثوقة','CLIENT','p136-engine','p136-policy',repeat('e',64),'Fixture comportementale P136','13600000-0000-4000-8000-000000000001');
insert into public.questionnaire_sessions(id,organization_id,actor_user_id,library_id,catalog_release_id,questionnaire_version_id,audience,locale,status,submitted_at,answer_manifest,answer_manifest_hash)values('13680000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001','13600000-0000-4000-8000-000000000001','13683000-0000-4000-8000-000000000001','13684000-0000-4000-8000-000000000001','13682000-0000-4000-8000-000000000001','CLIENT','fr-MA','SUBMITTED',clock_timestamp(),'{}',repeat('c',64));
insert into public.client_profile_versions(id,compliance_case_id,organization_id,version,profile_data,organization_snapshot,source_organization_row_version,created_by)values('13690000-0000-4000-8000-000000000001','13670000-0000-4000-8000-000000000001','13610000-0000-4000-8000-000000000001',1,'{}','{}',1,'13600000-0000-4000-8000-000000000001');
select extensions.is((select reason_code from public.diagnostic_reevaluation_queue where questionnaire_session_id='13680000-0000-4000-8000-000000000001'),'PROFILE_CHANGED','authoritative profile version queues diagnostic reevaluation');
select extensions.is((select count(*)::integer from public.audit_events where resource_id='13680000-0000-4000-8000-000000000001'and action='diagnostic.reevaluation.profile_changed.queued'),1,'profile-change producer appends one audit proof');
select extensions.is((select count(*)::integer from public.event_outbox where aggregate_id='13680000-0000-4000-8000-000000000001'and event_type='DiagnosticReevaluationQueuedV1'),1,'profile-change producer emits one versioned event');
create temp table p136_claim(value jsonb);create temp table p136_authorization(value jsonb);create temp table p136_scheduler(value jsonb);grant select,insert,delete on p136_claim,p136_authorization,p136_scheduler to service_role;grant usage on schema extensions to service_role;grant execute on all functions in schema extensions to service_role;grant select,update on public.notification_deliveries to service_role;grant select on public.notification_delivery_attempts,public.event_outbox to service_role;
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into p136_claim select*from public.claim_notification_deliveries_v1('p136-worker-one',1,60);
insert into p136_authorization select public.authorize_notification_delivery_send_v1('13660000-0000-4000-8000-000000000001',(select(value->>'lease_token')::uuid from p136_claim),'p136-worker-one','13650000-0000-4000-8000-000000000004');
select extensions.ok((select count(*)=1 from p136_claim)and(select(value->>'authorized')::boolean from p136_authorization),'first worker claims and pre-send authorizes mandatory delivery with versioned legal basis');
select extensions.ok((select count(*)=0 from public.claim_notification_deliveries_v1('p136-worker-two',1,60)),'concurrent worker cannot claim active lease');
select extensions.is((public.record_notification_delivery_worker_result_v1('13660000-0000-4000-8000-000000000001',(select(value->>'lease_token')::uuid from p136_claim),'p136-worker-one','RETRYABLE_FAILURE',null,'TRANSIENT','{}','p136-attempt-1','13650000-0000-4000-8000-000000000002')->>'status'),'FAILED','retryable failure is scheduled');
select extensions.ok((select next_attempt_at is not null and lease_token is null and attempt_count=1 from public.notification_deliveries where id='13660000-0000-4000-8000-000000000001'),'retry clears lease and preserves due retry');
update public.notification_deliveries set next_attempt_at=clock_timestamp()-interval'1 second'where id='13660000-0000-4000-8000-000000000001';delete from p136_claim;insert into p136_claim select*from public.claim_notification_deliveries_v1('p136-worker-one',1,60);
select extensions.is((public.record_notification_delivery_worker_result_v1('13660000-0000-4000-8000-000000000001',(select(value->>'lease_token')::uuid from p136_claim),'p136-worker-one','PERMANENT_FAILURE',null,'DENIED','{}','p136-attempt-2','13650000-0000-4000-8000-000000000003')->>'status'),'DEAD_LETTER','permanent failure dead-letters');
select extensions.is((public.record_notification_delivery_worker_result_v1('13660000-0000-4000-8000-000000000001',(select(value->>'lease_token')::uuid from p136_claim),'p136-worker-one','PERMANENT_FAILURE',null,'DENIED','{}','p136-attempt-2','13650000-0000-4000-8000-000000000003')->>'outcome'),'NOTIFICATION_RESULT_REPLAYED','identical replay succeeds before terminal lease guards');
select extensions.throws_ok(format($$select public.record_notification_delivery_worker_result_v1('13660000-0000-4000-8000-000000000001',%L,'p136-worker-one','PERMANENT_FAILURE',null,'CHANGED','{}','p136-attempt-2','13650000-0000-4000-8000-000000000003')$$,(select value->>'lease_token'from p136_claim)),'22000'::char(5),'IDEMPOTENCY_PAYLOAD_MISMATCH','same key with changed payload is denied before lease guards');
select extensions.ok((select terminal_at is not null and next_attempt_at is null and attempt_count=2 from public.notification_deliveries where id='13660000-0000-4000-8000-000000000001'),'DLQ is terminal and immutable through dispatcher');
select extensions.ok((select count(*)=2 from public.notification_delivery_attempts where delivery_id='13660000-0000-4000-8000-000000000001'),'attempt evidence is append-only and deduplicated');
select extensions.ok((select count(*)=2 from public.event_outbox where aggregate_id='13660000-0000-4000-8000-000000000001'and event_type in('NotificationDeliveryRetryScheduledV1','NotificationDeadLetteredV1')),'retry and DLQ emit durable events');
reset role;update public.notification_deliveries set next_attempt_at=clock_timestamp()-interval'1 second'where id='13660000-0000-4000-8000-000000000002';set local role service_role;delete from p136_claim;insert into p136_claim select*from public.claim_notification_deliveries_v1('p136-worker-one',1,60);reset role;delete from public.user_notification_preferences where category_code='P136_OPTIONAL';set local role service_role;
select extensions.is((public.authorize_notification_delivery_send_v1('13660000-0000-4000-8000-000000000002',(select(value->>'lease_token')::uuid from p136_claim),'p136-worker-one','13650000-0000-4000-8000-000000000006')->>'authorized')::boolean,false,'pre-send recheck blocks optional email after preference withdrawal');
insert into p136_scheduler select public.run_domain_automation_schedulers_v1(current_date+31,1);
reset role;
select extensions.is((select value->>'outcome'from p136_scheduler),'DOMAIN_AUTOMATIONS_COMPLETED','scheduler executes its four domain projections');
select extensions.is((select status from public.diagnostic_reevaluation_queue where questionnaire_session_id='13680000-0000-4000-8000-000000000001'),'WAITING_USER','scheduler consumes a non-empty diagnostic queue exactly once');
select extensions.is((select count(*)::integer from public.domain_automation_runs where as_of=current_date+31),4,'scheduler appends four immutable run proofs');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);delete from p136_scheduler;insert into p136_scheduler select public.run_domain_automation_schedulers_v1(current_date+31,1);reset role;
select extensions.is((select value->>'outcome'from p136_scheduler),'DOMAIN_AUTOMATIONS_REPLAYED','completed scheduler date replays without rerunning effects');
select extensions.throws_ok($$update public.domain_automation_runs set result_snapshot='{}'where as_of=current_date+31$$,'55000'::char(5),'IMMUTABLE_DOMAIN_AUTOMATION_RUN','scheduler run evidence cannot be rewritten');
select extensions.throws_ok($$delete from public.domain_automation_runs where as_of=current_date+31$$,'55000'::char(5),'IMMUTABLE_DOMAIN_AUTOMATION_RUN','scheduler run evidence cannot be deleted');
select*from finish();rollback;
